860	    public function getSiteLinkBlocks(string $siteId): array
861	    {
862	        // Single-flight + ±20% jitter + SWR via CacheLockService. Without the
863	        // lock, a cold cache after a flush lets every concurrent visitor on a
864	        // popular site rebuild this list in parallel; with int TTL the helper
865	        // also spreads expiry across the fleet.
866	        return $this->cacheLock->rememberLocked(
867	            CacheKeyGenerator::siteBlocks($siteId, 'links'),
868	            self::PAYLOAD_TTL_SECONDS,
869	            fn () => Block::query()
870	                ->where('site_id', $siteId)
871	                ->where('block_group', 'links')
872	                ->active()
873	                ->orderBy('sort_order')
874	                ->get()
875	                ->toArray()
876	        );
877	    }
