8	use Illuminate\Support\Facades\Cache;
9	
10	// V2: Visit/click stats caching with version-token invalidation for bulk cache busting.
11	class AnalyticsCacheService
12	{
13	    public function __construct(private CacheLockService $cacheLock) {}
14	
15	    public function getVisitStats(string $professionalId, Carbon $startDate, Carbon $endDate): array
16	    {
17	        $cacheKey = CacheKeyGenerator::analyticsVisits(
18	            $professionalId,
19	            $startDate->format('Ymd'),
20	            $endDate->format('Ymd')
21	        );
22	
23	        return $this->cacheLock->rememberLocked($cacheKey, now()->addMinutes(5), function () use ($professionalId, $startDate, $endDate) {
24	            return SiteVisit::where('professional_id', $professionalId)
25	                ->whereBetween('occurred_at', [$startDate, $endDate])
26	                ->selectRaw('
27	                    COUNT(*) as total_visits,
28	                    COUNT(DISTINCT visitor_id) as unique_visitors,
29	                    COUNT(DISTINCT DATE(occurred_at)) as days_with_visits,
30	                    COUNT(DISTINCT country_code) as unique_countries,
31	                    COUNT(DISTINCT device_type) as device_types
32	                ')
33	                ->first()
34	                ?->toArray() ?? [
35	                    'total_visits' => 0,
36	                    'unique_visitors' => 0,
37	                    'days_with_visits' => 0,
38	                    'unique_countries' => 0,
39	                    'device_types' => 0,
40	                ];
41	        });
42	    }
43	
44	    public function getClickStats(string $professionalId, Carbon $startDate, Carbon $endDate): array
45	    {
46	        $cacheKey = CacheKeyGenerator::analyticsClicks(
47	            $professionalId,
48	            $startDate->format('Ymd'),
49	            $endDate->format('Ymd')
50	        );
51	
52	        return $this->cacheLock->rememberLocked($cacheKey, now()->addMinutes(5), function () use ($professionalId, $startDate, $endDate) {
53	            return LinkClick::runForBlockForeignKey(
54	                function (string $blockColumn) use ($professionalId, $startDate, $endDate) {
55	                    return LinkClick::where('professional_id', $professionalId)
56	                        ->whereBetween('occurred_at', [$startDate, $endDate])
57	                        ->selectRaw("
58	                            COUNT(*) as total_clicks,
59	                            COUNT(DISTINCT visitor_id) as unique_clickers,
60	                            COUNT(DISTINCT {$blockColumn}) as links_clicked
61	                        ")
62	                        ->first()
63	                        ?->toArray() ?? [
64	                            'total_clicks' => 0,
65	                            'unique_clickers' => 0,
66	                            'links_clicked' => 0,
67	                        ];
68	                },
69	                [
70	                    'total_clicks' => 0,
71	                    'unique_clickers' => 0,
72	                    'links_clicked' => 0,
73	                ]
74	            );
75	        });
76	    }
77	
78	    public function invalidateAnalytics(string $professionalId): void
79	    {
80	        // Bump the version token so every cached summary for this professional
81	        // becomes unreachable immediately, regardless of date-range or granularity.
82	        // The stale entries will expire on their own TTL (≤ 24 h).
83	        Cache::increment(CacheKeyGenerator::analyticsSummaryVersion($professionalId));
84	
85	        // Drop every variant of the affiliate projections cache (adaptive default + each
86	        // window-tier override). Driven from config so that adding/removing a tier in
87	        // `partna.commerce_analytics.projections_window_tiers` automatically updates
88	        // invalidation — pragmatic explicit list rather than wildcard SCAN.
89	        $projectionVariants = array_merge(
90	            [null],
91	            (array) config('partna.commerce_analytics.projections_window_tiers', [90, 60, 30, 14])
92	        );
93	        foreach ($projectionVariants as $w) {
94	            $w = $w === null ? null : (int) $w;
95	            Cache::forget(CacheKeyGenerator::affiliateProjections($professionalId, $w));
96	            Cache::forget(CacheKeyGenerator::affiliateProjections($professionalId, $w).':stale');
97	        }
98	
99	        // Delete the rolling 90-day window of visit and click stat keys.
100	        // Each entry covers a single day (start === end === that day's date).
101	        $keys = [];
102	
103	        for ($i = 0; $i < 90; $i++) {
104	            $date = Carbon::now()->subDays($i)->format('Ymd');
105	
106	            $keys[] = CacheKeyGenerator::analyticsVisits($professionalId, $date, $date);
107	            $keys[] = CacheKeyGenerator::analyticsClicks($professionalId, $date, $date);
108	        }
109	
110	        Cache::deleteMultiple(array_values(array_unique($keys)));
111	    }
112	}
