127	    /* ---------------------------
128	     |  Keep model-returning helpers (no model caching)
129	     * --------------------------*/
130	
131	    /**
132	     * Resolve a Professional by their Supabase auth UUID.
133	     *
134	     * auth_user_id is immutable — set at account creation, never updated — so there is
135	     * no real mid-request race between the cached ID lookup and the model fetch.
136	     * The mismatch guard below is a belt-and-suspenders defence against stale/corrupt
137	     * cache entries only, not a concurrency fix.
138	     *
139	     * Two-level cache:
140	     *   1. id lookup (`pro:map:auth:{uid}`) — 30 min, immutable mapping
141	     *   2. hydrated model (`pro:model:{id}`) — 60 s with SWR + jitter via CacheLockService
142	     *
143	     * The model layer is what makes the auth path a Redis hit instead of a Postgres
144	     * round-trip on every authenticated request. Eloquent models serialize cleanly
145	     * through Redis; relations preserved across the boundary stay marked as loaded
146	     * (so `$pro->site` does not silently re-query). Bust both keys on profile writes
147	     * via `invalidateProfessional()`.
148	     */
149	    public function getByAuthId(string $authUserId): ?Professional
150	    {
151	        $id = $this->getIdByAuthId($authUserId);
152	        if (! $id) {
153	            return null;
154	        }
155	
156	        // Cache the hydrated model for 60s with SWR + jitter. Eager-loading site +
157	        // squareIntegration here makes them effectively free for every authenticated
158	        // request — they ride along inside the cached model, paid once per 60s window.
159	        $professional = $this->cacheLock->rememberLocked(
160	            CacheKeyGenerator::professionalModel($id),
161	            60,
162	            fn () => Professional::query()->with(['site', 'squareIntegration'])->find($id),
163	        );
164	        if (! $professional) {
165	            return null;
166	        }
167	
168	        // Defensive guard: if cache is stale/corrupt, never return another user's profile.
169	        if ((string) $professional->auth_user_id !== $authUserId) {
170	            $authIdKey = CacheKeyGenerator::professionalIdByAuthId($authUserId);
171	            $modelKey = CacheKeyGenerator::professionalModel($id);
172	            Cache::forget($authIdKey);
173	            Cache::forget($modelKey);
174	            Cache::forget($modelKey.':stale');
175	
176	            $freshId = Professional::query()
177	                ->where('auth_user_id', $authUserId)
178	                ->value('id');
179	
180	            if (! $freshId) {
181	                return null;
182	            }
183	
184	            Cache::put($authIdKey, $freshId, now()->addMinutes(30));
185	
186	            return Professional::query()->with(['site', 'squareIntegration'])->find($freshId);
187	        }
188	
189	        return $professional;
190	    }
