30	query allProducts($first: Int!, $after: String) {
31	  products(first: $first, after: $after) {
32	    edges {
33	      node {
34	        id
35	        title
36	        handle
37	        status
38	        description
39	        featuredImage { url altText }
40	        # Gallery for the brand detail modal — five is plenty for the
41	        # modal carousel and fits within Shopify's 1000-point cost budget.
42	        # Cost math on this query: products(50) + variants(50·5=250) +
43	        # images(50·5=250) + metafields(50·5=250) = 800, safely under.
44	        images(first: 5) { edges { node { url altText } } }
45	        priceRange {
46	          minVariantPrice { amount currencyCode }
47	          maxVariantPrice { amount currencyCode }
48	        }
49	        # Variants + per-variant sidest.enabled state — needed by the brand
50	        # catalog table to render the expand chevron on multi-variant
51	        # products and the per-variant enable/disable toggle.
52	        #
53	        # Cost math on this query (Shopify's 1000-point-per-request budget):
54	        #   products(first: 50)             = 50
55	        #   variants(first: N) × 50         = 50·N
56	        #   images(first: 1) × 50           = 50
57	        #   5 metafields × 50               = 250
58	        #   ── total                       ≈ 350 + 50·N
59	        # Capping variants at 5 lands us at ~600, a comfortable margin. If a
60	        # brand has >5 variants on a product the catalog still shows the
61	        # ones it can and the single-product detail queries elsewhere in
62	        # this service fetch the full list on demand.
63	        variants(first: 5) {
64	          edges {
65	            node {
66	              id
67	              title
68	              availableForSale
69	              # Admin API's ProductVariant.price is a `Money` scalar (decimal
70	              # string like "29.99"), not a MoneyV2 object — doing subselections
71	              # here fails with "Selections can't be made on scalars". Currency
72	              # comes from the parent product's priceRange.minVariantPrice.
73	              price
74	              metafield_enabled: metafield(namespace: "sidest", key: "enabled") { value }
75	            }
76	          }
77	        }
78	        metafield_active: metafield(namespace: "sidest", key: "active") { value }
79	        metafield_commission: metafield(namespace: "sidest", key: "commission_override") { value }
80	        metafield_discount: metafield(namespace: "sidest", key: "affiliate_discount_pct") { value }
81	        metafield_custom_photos: metafield(namespace: "sidest", key: "custom_photos_enabled") { value }
82	        metafield_has_enabled_variants: metafield(namespace: "sidest", key: "has_enabled_variants") { value }
83	      }
