287	    /**
288	     * Diagnostic probe: two modes.
289	     *
290	     *   mode = 'minimal' (default)
291	     *     Runs a hand-rolled minimal query (shop + products(first:3) with
292	     *     just id/title/status). Confirms auth works and returns a sample.
293	     *
294	     *   mode = 'all'
295	     *     Runs the exact same ALL_PRODUCTS query that /brand/catalog/all uses,
296	     *     with the same PRODUCTS_PER_PAGE variable, and returns the raw
297	     *     Shopify response — so we can see the full cost breakdown, any
298	     *     errors, and the actual edge count for the real query.
299	     *
300	     * Both modes surface Shopify's errors array, the extensions.cost
301	     * breakdown, the HTTP status, and the locally-stored scope list.
302	     */
303	    public function probeProductsQuery(Professional $brand, string $mode = 'minimal'): array
304	    {
305	        $resolved = $this->resolveBrandIntegration($brand);
306	        $shopDomain = $resolved['shop_domain'];
307	        $accessToken = $resolved['access_token'];
308	        $metadata = $resolved['metadata'];
309	        $apiVersion = (string) config('services.shopify.api_version', '2025-01');
310	
311	        $minimalQuery = <<<'GRAPHQL'
312	        query probe {
313	          shop { id name myshopifyDomain }
314	          products(first: 3) {
315	            edges { node { id title status } }
316	            pageInfo { hasNextPage }
317	          }
318	        }
319	        GRAPHQL;
320	
321	        [$query, $variables] = $mode === 'all'
322	            ? [self::ALL_PRODUCTS, ['first' => self::PRODUCTS_PER_PAGE]]
323	            : [$minimalQuery, []];
324	
325	        $httpStatus = 0;
326	        $responseBody = [];
327	        try {
328	            $response = $this->client->graphql(
329	                $shopDomain,
330	                $accessToken,
331	                $apiVersion,
332	                $query,
333	                $variables,
334	                timeoutSeconds: 15,
335	            );
336	            $httpStatus = $response->status();
337	            $responseBody = $response->json() ?? [];
338	        } catch (\App\Exceptions\Shopify\ShopifyTransportException $e) {
339	            $httpStatus = $e->status;
340	            Log::warning('Shopify probe: request failed', ['error' => $e->getMessage(), 'mode' => $mode]);
341	        } catch (\App\Exceptions\Shopify\ShopifyGraphQLException $e) {
342	            $httpStatus = 200;
343	            $responseBody = ['errors' => $e->graphqlErrors];
344	            Log::warning('Shopify probe: GraphQL errors', ['errors' => $e->graphqlErrors, 'mode' => $mode]);
345	        } catch (\Throwable $e) {
346	            Log::warning('Shopify probe: request failed', ['error' => $e->getMessage(), 'mode' => $mode]);
347	        }
348	
349	        $edges = Arr::get($responseBody, 'data.products.edges', []);
350	        $sample = array_map(
351	            fn (array $edge) => [
352	                'id' => (string) Arr::get($edge, 'node.id', ''),
353	                'title' => (string) Arr::get($edge, 'node.title', ''),
354	                'status' => (string) Arr::get($edge, 'node.status', ''),
355	            ],
356	            is_array($edges) ? array_slice($edges, 0, 5) : []
357	        );
358	
359	        return [
360	            'mode' => $mode,
361	            'shop' => Arr::get($responseBody, 'data.shop'),
362	            'products_total_edges' => is_array($edges) ? count($edges) : 0,
363	            'products_sample' => $sample,
364	            'page_info' => Arr::get($responseBody, 'data.products.pageInfo'),
365	            'errors' => Arr::get($responseBody, 'errors', []),
366	            'cost' => Arr::get($responseBody, 'extensions.cost'),
367	            'http_status' => $httpStatus,
368	            'scopes_granted' => is_array(Arr::get($metadata, 'scopes')) ? Arr::get($metadata, 'scopes') : [],
369	        ];
370	    }
