386	    /**
387	     * Fetch the sidest.commission_override metafield for a set of product GIDs
388	     * in a single Admin API call. Returns a map keyed by product GID; value is
389	     * the float override or null when the metafield is unset.
390	     *
391	     * Used by ProcessShopifyOrderWebhookJob to resolve commission rates
392	     * server-side instead of trusting buyer-set cart line attributes.
393	     *
394	     * @param  array<int, string>  $productGids
395	     * @return array<string, float|null>
396	     */
397	    public function fetchCommissionOverridesForProducts(ProfessionalIntegration $integration, array $productGids): array
398	    {
399	        $productGids = array_values(array_unique(array_filter($productGids)));
400	        if (empty($productGids)) {
401	            return [];
402	        }
403	
404	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
405	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
406	        $accessToken = trim((string) $integration->access_token);
407	
408	        if ($shopDomain === '' || $accessToken === '') {
409	            return array_fill_keys($productGids, null);
410	        }
411	
412	        try {
413	            $response = $this->graphql(
414	                $shopDomain,
415	                $accessToken,
416	                self::COMMISSION_OVERRIDES_QUERY,
417	                ['ids' => $productGids]
418	            );
419	        } catch (\Throwable $e) {
420	            Log::warning('Failed to fetch commission overrides.', [
421	                'integration_id' => (string) $integration->id,
422	                'error' => $e->getMessage(),
423	            ]);
424	
425	            return array_fill_keys($productGids, null);
426	        }
427	
428	        $nodes = $response->json('data.nodes', []);
429	        $out = array_fill_keys($productGids, null);
430	
431	        if (is_array($nodes)) {
432	            foreach ($nodes as $node) {
433	                if (! is_array($node)) {
434	                    continue;
435	                }
436	                $gid = (string) ($node['id'] ?? '');
437	                if ($gid === '') {
438	                    continue;
439	                }
440	                $val = Arr::get($node, 'metafield.value');
441	                $out[$gid] = $val !== null ? (float) $val : null;
442	            }
443	        }
444	
445	        return $out;
446	    }
