499	    /**
500	     * Clear every `sidest.enabled = false` metafield on the product's variants.
501	     * Called when the product is activated (sidest.active flipped to true) so
502	     * the brand's expectation — "making the product available re-enables all
503	     * its variants" — is honoured in Shopify data, not just the dashboard UI.
504	     *
505	     * Strategy: read every variant with its current sidest.enabled value, then
506	     * flip any that are explicitly false back to true via metafieldsSet (one
507	     * batched call). Variants whose metafield is missing stay missing (dynamic
508	     * default = enabled). After the sweep, the product's has_enabled_variants
509	     * derived flag is rewritten to true since every variant now resolves to
510	     * enabled (or the product has no variants at all).
511	     *
512	     * Idempotent: if no variants are disabled, makes no writes.
513	     *
514	     * @return array{success: bool, cleared: int, userErrors: array}
515	     */
516	    public function clearVariantDisablesForProduct(ProfessionalIntegration $integration, string $productGid): array
517	    {
518	        $resolved = $this->resolveCredentials($integration);
519	
520	        // Fetch variant GIDs + current sidest.enabled metafield values in one go.
521	        // Same shape as the catalog query but scoped to a single product so
522	        // cost stays tiny regardless of catalog size.
523	        $query = <<<'GRAPHQL'
524	        query variantEnabledStates($productId: ID!) {
525	          product(id: $productId) {
526	            variants(first: 100) {
527	              edges {
528	                node {
529	                  id
530	                  metafield_enabled: metafield(namespace: "sidest", key: "enabled") { value }
531	                }
532	              }
533	            }
534	          }
535	        }
536	        GRAPHQL;
537	
538	        $response = $this->graphql($resolved['shop_domain'], $resolved['access_token'], $query, [
539	            'productId' => $productGid,
540	        ]);
541	
542	        $edges = Arr::get($response->json(), 'data.product.variants.edges', []);
543	        if (! is_array($edges)) {
544	            return ['success' => true, 'cleared' => 0, 'userErrors' => []];
545	        }
546	
547	        // Collect every variant currently marked explicitly disabled.
548	        $disabledVariantGids = [];
549	        foreach ($edges as $edge) {
550	            $node = $edge['node'] ?? [];
551	            $id = (string) Arr::get($node, 'id', '');
552	            $enabledRaw = Arr::get($node, 'metafield_enabled.value');
553	            if ($id === '' || $enabledRaw === null) {
554	                continue;
555	            }
556	            if (filter_var($enabledRaw, FILTER_VALIDATE_BOOLEAN) === false) {
557	                $disabledVariantGids[] = $id;
558	            }
559	        }
560	
561	        // Nothing to do — product's variants are all already enabled (or have
562	        // no metafield, which means default-enabled anyway).
563	        if (empty($disabledVariantGids)) {
564	            // Still refresh the derived flag so re-activating a product whose
565	            // has_enabled_variants was previously false (e.g. from an earlier
566	            // bulk-disable) lands in a correct smart-collection state.
567	            $this->writeHasEnabledVariants($integration, $productGid, true);
568	
569	            return ['success' => true, 'cleared' => 0, 'userErrors' => []];
570	        }
571	
572	        // Flip each previously-false sidest.enabled to true.
573	        $metafields = array_map(fn (string $variantGid) => [
574	            'namespace' => 'sidest',
575	            'key' => 'enabled',
576	            'value' => 'true',
577	            'type' => 'boolean',
578	            'ownerId' => $variantGid,
579	        ], $disabledVariantGids);
580	
581	        foreach (array_chunk($metafields, 25) as $batch) {
582	            $writeResponse = $this->graphql($resolved['shop_domain'], $resolved['access_token'], self::METAFIELDS_SET, [
583	                'metafields' => $batch,
584	            ]);
585	
586	            $userErrors = Arr::get($writeResponse->json(), 'data.metafieldsSet.userErrors', []);
587	            if (! empty($userErrors)) {
588	                return ['success' => false, 'cleared' => 0, 'userErrors' => $userErrors];
589	            }
590	        }
591	
592	        // Cache bust — variant state affects both brand and affiliate catalog views.
593	        Cache::forget(CacheKeyGenerator::brandAdminCatalog((string) $integration->professional_id));
594	        Cache::forget(CacheKeyGenerator::brandActiveCatalog((string) $integration->professional_id));
595	
596	        // Recompute the derived has_enabled_variants flag — now trivially true.
597	        $this->writeHasEnabledVariants($integration, $productGid, true);
598	
599	        return ['success' => true, 'cleared' => count($disabledVariantGids), 'userErrors' => []];
600	    }
