632	    /**
633	     * Set variant-level sidest.enabled metafields. Writes `false` on disabled variants
634	     * and `true` on all others to clear any previous restriction. Uses a single
635	     * metafieldsSet mutation (batched at 25 if the product has many variants).
636	     *
637	     * Also recomputes and writes sidest.has_enabled_variants on the parent product:
638	     * true if at least one variant is not disabled, false if every variant is
639	     * disabled. This drives the Active Products smart collection condition so a
640	     * product with no enabled variants falls out of affiliate-facing surfaces
641	     * automatically, without the brand having to flip sidest.active themselves.
642	     *
643	     * @param  string  $productGid  Parent product GID (used to write the derived product metafield)
644	     * @param  array<int, string>  $allVariantGids  Every variant GID for the product (pre-fetched for validation)
645	     * @param  array<int, string>  $disabledVariantGids  Variant GIDs to mark as disabled
646	     * @return array{success: bool, userErrors: array}
647	     */
648	    public function setVariantEnabledStates(ProfessionalIntegration $integration, string $productGid, array $allVariantGids, array $disabledVariantGids = []): array
649	    {
650	        if (empty($allVariantGids)) {
651	            // No variants on this product — has_enabled_variants is trivially true.
652	            // Write it anyway so newly created products get an explicit value and the
653	            // Active Products smart collection picks them up.
654	            return $this->writeHasEnabledVariants($integration, $productGid, true);
655	        }
656	
657	        $disabled = array_flip($disabledVariantGids);
658	        $resolved = $this->resolveCredentials($integration);
659	
660	        $metafields = array_map(fn (string $variantGid) => [
661	            'namespace' => 'sidest',
662	            'key' => 'enabled',
663	            'value' => isset($disabled[$variantGid]) ? 'false' : 'true',
664	            'type' => 'boolean',
665	            'ownerId' => $variantGid,
666	        ], $allVariantGids);
667	
668	        // Shopify limits metafieldsSet to 25 inputs per call
669	        foreach (array_chunk($metafields, 25) as $batch) {
670	            $response = $this->graphql($resolved['shop_domain'], $resolved['access_token'], self::METAFIELDS_SET, [
671	                'metafields' => $batch,
672	            ]);
673	
674	            $userErrors = Arr::get($response->json(), 'data.metafieldsSet.userErrors', []);
675	
676	            if (! empty($userErrors)) {
677	                return ['success' => false, 'userErrors' => $userErrors];
678	            }
679	        }
680	
681	        // Bust caches — variant state affects both brand and affiliate views
682	        Cache::forget(CacheKeyGenerator::brandAdminCatalog((string) $integration->professional_id));
683	        Cache::forget(CacheKeyGenerator::brandActiveCatalog((string) $integration->professional_id));
684	
685	        // Recompute and persist the derived product-level flag
686	        $hasEnabled = count($disabledVariantGids) < count($allVariantGids);
687	
688	        return $this->writeHasEnabledVariants($integration, $productGid, $hasEnabled);
689	    }
