691	    /**
692	     * Write the derived sidest.has_enabled_variants metafield on a product. Separated
693	     * out so the backfill command can call it with a precomputed value without
694	     * re-writing every variant metafield.
695	     *
696	     * @return array{success: bool, userErrors: array}
697	     */
698	    public function writeHasEnabledVariants(ProfessionalIntegration $integration, string $productGid, bool $value): array
699	    {
700	        $resolved = $this->resolveCredentials($integration);
701	
702	        $response = $this->graphql($resolved['shop_domain'], $resolved['access_token'], self::METAFIELDS_SET, [
703	            'metafields' => [[
