958	    private function graphql(string $shopDomain, string $accessToken, string $query, array $variables): \Illuminate\Http\Client\Response
959	    {
960	        $apiVersion = config('services.shopify.api_version', '2025-01');
961	
962	        // Client throws ShopifyTransportException on non-2xx and ShopifyGraphQLException
963	        // on top-level errors — both propagate as RuntimeException for the caller.
964	        return $this->client->graphql(
965	            $shopDomain,
966	            $accessToken,
967	            $apiVersion,
968	            $query,
969	            $variables,
970	        );
