975	     */
976	    private function bustCatalogCaches(ProfessionalIntegration $integration, array $metafields, ?string $productGid = null): void
977	    {
978	        $brandId = (string) $integration->professional_id;
979	
980	        // Always bust the admin catalog cache
981	        Cache::forget(CacheKeyGenerator::brandAdminCatalog($brandId));
982	
983	        $touchedKeys = array_column($metafields, 'key');
984	
985	        // If 'active' was changed, also bust the affiliate-facing catalog cache
986	        if (in_array('active', $touchedKeys, true)) {
987	            Cache::forget(CacheKeyGenerator::brandActiveCatalog($brandId));
988	        }
989	
990	        // If per-product custom_photos_enabled was changed, bust the targeted lookup cache
991	        if ($productGid !== null && in_array('custom_photos_enabled', $touchedKeys, true)) {
992	            Cache::forget(CacheKeyGenerator::brandProductCustomPhotos($brandId, $productGid));
993	        }
994	    }
