1012	            if ($cursor !== null) {
1013	                $variables['after'] = $cursor;
1014	            }
1015	
1016	            try {
1017	                $response = $this->graphql($shopDomain, $accessToken, self::PRODUCTS_WITH_METAFIELDS, $variables);
1018	                $data = $response->json();
1019	
1020	                // Log GraphQL errors if present
1021	                if (! empty($data['errors'])) {
1022	                    Log::error('Shopify catalog GraphQL errors.', [
1023	                        'brand_id' => (string) $brand->id,
1024	                        'errors' => $data['errors'],
1025	                    ]);
1026	                }
1027	
1028	                $edges = Arr::get($data, 'data.products.edges', []);
1029	                if (! is_array($edges)) {
