1058	                                : null,
1059	                            'enabled' => $enabledVal !== null ? filter_var($enabledVal, FILTER_VALIDATE_BOOLEAN) : null,
1060	                        ];
1061	                    }
1062	
1063	                    $activeVal = Arr::get($node, 'metafield_active.value');
1064	                    $commissionVal = Arr::get($node, 'metafield_commission.value');
1065	                    $discountVal = Arr::get($node, 'metafield_discount.value');
1066	                    $customPhotosVal = Arr::get($node, 'metafield_custom_photos.value');
1067	                    $hasEnabledVariantsVal = Arr::get($node, 'metafield_has_enabled_variants.value');
1068	
1069	                    $products[] = [
1070	                        'gid' => $node['id'] ?? '',
1071	                        'title' => $node['title'] ?? '',
1072	                        'handle' => $node['handle'] ?? '',
1073	                        'status' => $node['status'] ?? 'ACTIVE',
1074	                        'featured_image' => $node['featuredImage'] ?? null,
1075	                        'price_range' => [
1076	                            'min' => Arr::get($node, 'priceRange.minVariantPrice'),
1077	                            'max' => Arr::get($node, 'priceRange.maxVariantPrice'),
1078	                        ],
1079	                        'variants' => $variants,
1080	                        'metafields' => [
