1082	                            'commission_override' => $commissionVal !== null ? (float) $commissionVal : null,
1083	                            'affiliate_discount_pct' => $discountVal !== null ? (float) $discountVal : null,
1084	                            'custom_photos_enabled' => $customPhotosVal !== null ? filter_var($customPhotosVal, FILTER_VALIDATE_BOOLEAN) : null,
1085	                            // null = unwritten (pre-backfill); true/false = explicit. The backfill
1086	                            // command populates this for existing products; new writes go through
1087	                            // writeHasEnabledVariants on every variant-state change.
1088	                            'has_enabled_variants' => $hasEnabledVariantsVal !== null ? filter_var($hasEnabledVariantsVal, FILTER_VALIDATE_BOOLEAN) : null,
1089	                        ],
1090	                    ];
1091	                }
1092	
1093	                $hasNextPage = Arr::get($data, 'data.products.pageInfo.hasNextPage', false);
1094	            } catch (\Throwable $e) {
1095	                Log::error('Failed to fetch brand admin catalog.', [
1096	                    'brand_id' => (string) $brand->id,
